sksl:
uniform shader image;
uniform float2 size;
uniform float amount;
uniform float centerX;
uniform float centerY;
uniform float sizeFlare;
layout(color) uniform half4 tint;
half4 effectMain(float2 coord){half4 c=image.eval(coord);float2 p=coord/size-float2(centerX,centerY);float r=length(p);float spot=exp(-r*r/max(sizeFlare*sizeFlare,0.0001)*8.0);return half4(clamp(c.rgb+tint.rgb*half(spot*amount)*c.a,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
